###############################################################################
# DOM implementation using Python's minidom-like tree
###############################################################################

VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr',
}

class Node:
    ELEMENT_NODE = 1
    TEXT_NODE = 3
    COMMENT_NODE = 8
    DOCUMENT_NODE = 9

    def __init__(self, node_type, parent=None):
        self.node_type = node_type
        self.parent = parent
        self.children = []

    def get_text(self):
        """Recursively get text content"""
        result = []
        for child in self.children:
            if child.node_type == Node.TEXT_NODE:
                result.append(child.data)
            elif child.node_type == Node.ELEMENT_NODE:
                result.extend(child.get_text())
        return result

class Document(Node):
    def __init__(self):
        super().__init__(Node.DOCUMENT_NODE)

    @property
    def document_element(self):
        for child in self.children:
            if child.node_type == Node.ELEMENT_NODE and child.tag_name.lower() == 'html':
                return child
        return None

class Element(Node):
    def __init__(self, tag_name, attrs=None, parent=None):
        super().__init__(Node.ELEMENT_NODE, parent)
        self.tag_name = tag_name.lower()
        self.attrs = attrs or {}  # dict: attr_name -> value
        self._id = None
        self._classes = None

    @property
    def id(self):
        if self._id is None:
            self._id = self.attrs.get('id', '')
        return self._id

    @property 
    def classes(self):
        if self._classes is None:
            cls = self.attrs.get('class', '')
            self._classes = set(cls.split()) if cls else set()
        return self._classes

    def get_attribute(self, name):
        return self.attrs.get(name)

    def has_attribute(self, name):
        return name in self.attrs

    @property
    def index_in_parent(self):
        """1-based index of this element among siblings of same tag"""
        if not self.parent:
            return 1
        idx = 0
        for child in self.parent.children:
            if child.node_type == Node.ELEMENT_NODE and child.tag_name == self.tag_name:
                idx += 1
                if child is self:
                    return idx
        return 1

class TextNode(Node):
    def __init__(self, data, parent=None):
        super().__init__(Node.TEXT_NODE, parent)
        self.data = data

class CommentNode(Node):
    def __init__(self, data, parent=None):
        super().__init__(Node.COMMENT_NODE, parent)
        self.data = data

