def _build_dom_from_h5lib(h5node, parent=None):
    """Recursively build our DOM from html5lib's DOM"""
    import xml.dom.minidom as minidom

    NODE_ELEMENT = minidom.Node.ELEMENT_NODE
    NODE_TEXT = minidom.Node.TEXT_NODE
    NODE_COMMENT = minidom.Node.COMMENT_NODE
    NODE_DOCUMENT = minidom.Node.DOCUMENT_NODE

    if h5node.nodeType == NODE_DOCUMENT:
        doc = Document()
        for child in h5node.childNodes:
            child_node = _build_dom_from_h5lib(child, doc)
            if child_node:
                doc.children.append(child_node)
                child_node.parent = doc
        return doc
    elif h5node.nodeType == NODE_ELEMENT:
        # Get tag name (remove namespace)
        tag = h5node.tagName
        if ':' in tag:
            tag = tag.split(':', 1)[1]
        tag = tag.lower()

        # Get attributes
        attrs = {}
        for i in range(h5node.attributes.length):
            attr = h5node.attributes.item(i)
            name = attr.name
            if ':' in name:
                name = name.split(':', 1)[1]
            attrs[name.lower()] = attr.value

        elem = Element(tag, attrs, parent)
        for child in h5node.childNodes:
            child_node = _build_dom_from_h5lib(child, elem)
            if child_node:
                elem.children.append(child_node)
                child_node.parent = elem
        return elem
    elif h5node.nodeType == NODE_TEXT:
        return TextNode(h5node.data, parent)
    elif h5node.nodeType == NODE_COMMENT:
        return CommentNode(h5node.data, parent)
    return None

def parse_with_html5lib(html_input):
