###############################################################################
# Fallback parser using Python's html.parser
###############################################################################

class HTML5Parser(html.parser.HTMLParser):
    """Build a DOM tree using Python's html.parser (fallback)"""

    # HTML5 void elements
    VOID_ELEMENTS = VOID_ELEMENTS

    # Elements that cause implicit parent closing (simplified)
    IMPLICIT_CLOSE = {
        'li': {'li'},
        'dt': {'dt', 'dd'},
        'dd': {'dt', 'dd'},
        'p': {'p'},
        'tr': {'tr'},
        'th': {'td', 'th'},
        'td': {'td', 'th'},
        'colgroup': {'colgroup'},
        'col': {'col'},
        'caption': set(),
        'thead': {'tbody', 'tfoot', 'thead'},
        'tbody': {'tbody', 'tfoot', 'thead'},
        'tfoot': {'tbody', 'tfoot', 'thead'},
        'option': {'option'},
        'optgroup': {'optgroup'},
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.doc = Document()
        self.stack = [self.doc]
        self._add_implicit_tags()

    def _add_implicit_tags(self):
        """Add implicit html, head, body elements"""
        html_elem = Element('html', {})
        head_elem = Element('head', {})
        body_elem = Element('body', {})

        html_elem.parent = self.doc
        head_elem.parent = html_elem
        body_elem.parent = html_elem

        self.doc.children.append(html_elem)
        html_elem.children.extend([head_elem, body_elem])

        self._html = html_elem
        self._head = head_elem
        self._body = body_elem

        # Stack: doc -> html -> body (default insertion point is body)
        self.stack = [self.doc, html_elem, self._body]

    @property
    def current(self):
        return self.stack[-1]

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {k.lower(): v or '' for k, v in attrs}

        # Handle implicit closings
        if tag in self.IMPLICIT_CLOSE:
            siblings_to_close = self.IMPLICIT_CLOSE[tag]
            if self.current.node_type == Node.ELEMENT_NODE and self.current.tag_name in siblings_to_close:
                self.stack.pop()

        # Special handling for head/body
        if tag in ('head', 'html', 'body'):
            return

        # Check if we should be in head vs body
        HEAD_ONLY = {'title', 'base', 'link', 'meta', 'script', 'style', 'noscript'}
        if tag in HEAD_ONLY and self._head in self.stack:
            parent = self._head
        else:
            parent = self.current
            # Make sure we're in body for non-head content
            if parent is self._html:
                parent = self._body
                self.stack.append(self._body)

        elem = Element(tag, attrs_dict, parent)
        parent.children.append(elem)

        if tag not in self.VOID_ELEMENTS:
            self.stack.append(elem)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag in ('html', 'body', 'head'):
            return

        # Pop until we find matching tag
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].node_type == Node.ELEMENT_NODE and self.stack[i].tag_name == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        parent = self.current
        if parent.node_type == Node.DOCUMENT_NODE:
            parent = self._body
        text = TextNode(data, parent)
        parent.children.append(text)

    def handle_comment(self, data):
        parent = self.current
        comment = CommentNode(data, parent)
        parent.children.append(comment)

def parse_with_stdlib(html_input):
    """Parse HTML using Python's stdlib html.parser (fallback)"""
    parser = HTML5Parser()
    parser.feed(html_input)
    return parser.doc

