class SelectorParser:
    """Parse CSS selector strings"""

    def __init__(self, selector_str):
        self.s = selector_str.strip()
        self.pos = 0

    def parse(self):
        """Parse a selector list (comma-separated selectors)"""
        selectors = []
        while self.pos < len(self.s):
            sel = self._parse_complex_selector()
            if sel:
                selectors.append(sel)
            self._skip_whitespace()
            if self.pos < len(self.s) and self.s[self.pos] == ',':
                self.pos += 1
                self._skip_whitespace()
        return SelectorList(selectors)

    def _skip_whitespace(self):
        while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r':
            self.pos += 1

    def _parse_complex_selector(self):
        """Parse a complex selector (combinators)"""
        left = self._parse_compound_selector()
        if left is None:
            return None

        parts = [left]
        combinators = []

        while self.pos < len(self.s):
            # Check for combinator
            start = self.pos
            has_whitespace = False

            while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r':
                has_whitespace = True
                self.pos += 1

            if self.pos >= len(self.s) or self.s[self.pos] in (',',):
                break

            if self.s[self.pos] == '>':
                self.pos += 1
                self._skip_whitespace()
                combinator = '>'
            elif self.s[self.pos] == '+':
                self.pos += 1
                self._skip_whitespace()
                combinator = '+'
            elif self.s[self.pos] == '~':
                self.pos += 1
                self._skip_whitespace()
                combinator = '~'
            elif has_whitespace:
                combinator = ' '
            else:
                self.pos = start
                break

            right = self._parse_compound_selector()
            if right is None:
                self.pos = start
                break

            combinators.append(combinator)
            parts.append(right)

        if len(parts) == 1:
            return parts[0]

        # Build complex selector
        result = parts[0]
        for i, comb in enumerate(combinators):
            result = CombinatorSelector(result, comb, parts[i+1])
        return result

    def _parse_compound_selector(self):
        """Parse a compound selector (multiple simple selectors)"""
        simples = []

        while self.pos < len(self.s):
            simple = self._parse_simple_selector()
            if simple is None:
                break
            simples.append(simple)

        if not simples:
            return None
        if len(simples) == 1:
            return simples[0]
        return CompoundSelector(simples)

    def _parse_simple_selector(self):
        """Parse a simple selector"""
        if self.pos >= len(self.s):
            return None

        c = self.s[self.pos]

        if c == '*':
            self.pos += 1
            return UniversalSelector()
        elif c == '#':
            self.pos += 1
            name = self._parse_ident()
            return IDSelector(name)
        elif c == '.':
            self.pos += 1
            name = self._parse_ident()
            return ClassSelector(name)
        elif c == '[':
            return self._parse_attribute_selector()
        elif c == ':':
            return self._parse_pseudo_selector()
        elif c.isalpha() or c == '_' or c == '-' or ord(c) > 127:
            name = self._parse_ident()
            return TagSelector(name.lower())

        return None

    def _parse_ident(self):
        start = self.pos
        while self.pos < len(self.s):
            c = self.s[self.pos]
            if c.isalnum() or c in '_-.' or ord(c) > 127:
                self.pos += 1
            else:
                break
        return self.s[start:self.pos]

    def _parse_attribute_selector(self):
        """Parse [attr], [attr=val], etc."""
        assert self.s[self.pos] == '['
        self.pos += 1
        self._skip_whitespace()

        attr_name = self._parse_ident()
        self._skip_whitespace()

        if self.pos >= len(self.s) or self.s[self.pos] == ']':
            if self.pos < len(self.s):
                self.pos += 1
            return AttributeSelector(attr_name, None, None)

        # Get operator
        op = ''
        if self.s[self.pos] in ('=', '~', '^', '$', '*', '|'):
            op = self.s[self.pos]
            self.pos += 1
            if op != '=' and self.pos < len(self.s) and self.s[self.pos] == '=':
                op += '='
                self.pos += 1

        self._skip_whitespace()

        # Get value
        val = ''
        if self.pos < len(self.s):
            if self.s[self.pos] in ('"', "'"):
                quote = self.s[self.pos]
                self.pos += 1
                start = self.pos
                while self.pos < len(self.s) and self.s[self.pos] != quote:
                    self.pos += 1
                val = self.s[start:self.pos]
                if self.pos < len(self.s):
                    self.pos += 1  # skip closing quote
            else:
                val = self._parse_ident()

        self._skip_whitespace()
        if self.pos < len(self.s) and self.s[self.pos] == ']':
            self.pos += 1

        return AttributeSelector(attr_name, op, val)

    def _parse_pseudo_selector(self):
        """Parse :pseudo-class or ::pseudo-element"""
        assert self.s[self.pos] == ':'
        self.pos += 1
        if self.pos < len(self.s) and self.s[self.pos] == ':':
            self.pos += 1  # ::pseudo-element
        name = self._parse_ident()

        # Handle functional pseudo-classes
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1
            # Read until matching )
            depth = 1
            start = self.pos
            while self.pos < len(self.s) and depth > 0:
                if self.s[self.pos] == '(':
                    depth += 1
                elif self.s[self.pos] == ')':
                    depth -= 1
                self.pos += 1
            arg = self.s[start:self.pos-1]
            return PseudoSelector(name, arg)

        return PseudoSelector(name, None)

###############################################################################
# Selector classes
###############################################################################

class SelectorList:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, element):
        return any(s.matches(element) for s in self.selectors)

    def select(self, root):
        """Find all elements matching any selector in the list"""
        # Use document order, no duplicates
        seen = set()
        results = []

        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if self.matches(node) and id(node) not in seen:
                    seen.add(id(node))
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif node.node_type == Node.DOCUMENT_NODE:
                for child in node.children:
                    traverse(child)

        traverse(root)
        return results

class UniversalSelector:
    def matches(self, element):
        return element.node_type == Node.ELEMENT_NODE

class TagSelector:
    def __init__(self, tag):
        self.tag = tag.lower()

    def matches(self, element):
        return element.node_type == Node.ELEMENT_NODE and element.tag_name == self.tag

class IDSelector:
    def __init__(self, id_val):
        self.id_val = id_val

    def matches(self, element):
        return element.node_type == Node.ELEMENT_NODE and element.id == self.id_val

class ClassSelector:
    def __init__(self, class_name):
        self.class_name = class_name

    def matches(self, element):
        return element.node_type == Node.ELEMENT_NODE and self.class_name in element.classes

class AttributeSelector:
    def __init__(self, attr, op, value):
        self.attr = attr.lower()
        self.op = op
        self.value = value

    def matches(self, element):
        if element.node_type != Node.ELEMENT_NODE:
            return False
        if not element.has_attribute(self.attr):
            return False
        if self.op is None:
            return True

        val = element.get_attribute(self.attr) or ''

        if self.op == '=':
            return val == self.value
        elif self.op == '~=':
            return self.value in val.split()
        elif self.op == '^=':
            return val.startswith(self.value)
        elif self.op == '$=':
            return val.endswith(self.value)
        elif self.op == '*=':
            return self.value in val
        elif self.op == '|=':
            return val == self.value or val.startswith(self.value + '-')

        return False

class PseudoSelector:
    def __init__(self, name, arg):
        self.name = name.lower()
        self.arg = arg

    def matches(self, element):
        if element.node_type != Node.ELEMENT_NODE:
            return False

        if self.name == 'first-child':
            return self._is_first_child(element)
        elif self.name == 'last-child':
            return self._is_last_child(element)
        elif self.name == 'first-of-type':
            return self._is_first_of_type(element)
        elif self.name == 'last-of-type':
            return self._is_last_of_type(element)
        elif self.name == 'nth-child':
            return self._nth_child(element, self.arg)
        elif self.name == 'nth-of-type':
            return self._nth_of_type(element, self.arg)
        elif self.name == 'only-child':
            return self._is_only_child(element)
        elif self.name == 'only-of-type':
            return self._is_only_of_type(element)
        elif self.name == 'not':
            sub = SelectorParser(self.arg).parse()
            return not sub.matches(element)
        elif self.name == 'root':
            return element.parent and element.parent.node_type == Node.DOCUMENT_NODE
        elif self.name in ('link', 'visited', 'hover', 'focus', 'active', 'checked',
                           'enabled', 'disabled', 'empty'):
            return False  # State pseudoclasses not applicable

        return False

    def _element_children(self, element):
        if not element.parent:
            return []
        return [c for c in element.parent.children if c.node_type == Node.ELEMENT_NODE]

    def _is_first_child(self, element):
        siblings = self._element_children(element)
        return siblings and siblings[0] is element

    def _is_last_child(self, element):
        siblings = self._element_children(element)
        return siblings and siblings[-1] is element

    def _is_first_of_type(self, element):
        if not element.parent:
            return True
        for child in element.parent.children:
            if child.node_type == Node.ELEMENT_NODE and child.tag_name == element.tag_name:
                return child is element
        return False

    def _is_last_of_type(self, element):
        if not element.parent:
            return True
        last = None
        for child in element.parent.children:
            if child.node_type == Node.ELEMENT_NODE and child.tag_name == element.tag_name:
                last = child
        return last is element

    def _is_only_child(self, element):
        siblings = self._element_children(element)
        return len(siblings) == 1 and siblings[0] is element

    def _is_only_of_type(self, element):
        if not element.parent:
            return True
        same_type = [c for c in element.parent.children 
                     if c.node_type == Node.ELEMENT_NODE and c.tag_name == element.tag_name]
        return len(same_type) == 1 and same_type[0] is element

    def _parse_nth(self, arg):
        """Parse nth selector: 2n+1, odd, even, 3, etc."""
        arg = arg.strip().lower()
        if arg == 'odd':
            return (2, 1)
        elif arg == 'even':
            return (2, 0)
        elif arg == 'n':
            return (1, 0)

        # Parse An+B
        m = re.match(r'^([+-]?\d+)?n([+-]\d+)?$', arg)
        if m:
            a = int(m.group(1)) if m.group(1) else (1 if 'n' in arg else 0)
            b = int(m.group(2)) if m.group(2) else 0
            return (a, b)

        m = re.match(r'^([+-]?\d+)$', arg)
        if m:
            return (0, int(m.group(1)))

        return (0, 0)

    def _nth_child(self, element, arg):
        a, b = self._parse_nth(arg)
        siblings = self._element_children(element)
        for i, sibling in enumerate(siblings):
            if sibling is element:
                n = i + 1  # 1-based
                if a == 0:
                    return n == b
                else:
                    return a > 0 and (n - b) % a == 0 and (n - b) // a >= 0
        return False

    def _nth_of_type(self, element, arg):
        a, b = self._parse_nth(arg)
        if not element.parent:
            return False
        same_type = [c for c in element.parent.children
                     if c.node_type == Node.ELEMENT_NODE and c.tag_name == element.tag_name]
        for i, sibling in enumerate(same_type):
            if sibling is element:
                n = i + 1
                if a == 0:
                    return n == b
                else:
                    return a > 0 and (n - b) % a == 0 and (n - b) // a >= 0
        return False

class CompoundSelector:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, element):
        return all(s.matches(element) for s in self.selectors)

class CombinatorSelector:
    def __init__(self, left, combinator, right):
        self.left = left
        self.combinator = combinator
        self.right = right

    def matches(self, element):
        if not self.right.matches(element):
            return False

        if self.combinator == ' ':  # Descendant
            ancestor = element.parent
            while ancestor:
                if self.left.matches(ancestor):
                    return True
                ancestor = ancestor.parent
            return False
        elif self.combinator == '>':  # Child
            return element.parent and self.left.matches(element.parent)
        elif self.combinator == '+':  # Adjacent sibling
            if not element.parent:
                return False
            prev = None
            for child in element.parent.children:
                if child is element:
                    return prev is not None and self.left.matches(prev)
                if child.node_type == Node.ELEMENT_NODE:
                    prev = child
            return False
        elif self.combinator == '~':  # General sibling
            if not element.parent:
                return False
            found_self = False
            for child in element.parent.children:
                if child is element:
                    found_self = True
                    break
                if child.node_type == Node.ELEMENT_NODE and self.left.matches(child):
                    found_self = True  # Will be verified next pass
            # Actually we need: some earlier sibling matches left
            for child in element.parent.children:
                if child is element:
                    return False
                if child.node_type == Node.ELEMENT_NODE and self.left.matches(child):
                    # Check if element comes after child
                    in_order = False
                    for c2 in element.parent.children:
                        if c2 is child:
                            in_order = True
                        elif c2 is element and in_order:
                            return True
            return False

def parse_selector(selector_str):
    """Parse a CSS selector string and return a SelectorList"""
    return SelectorParser(selector_str).parse()

###############################################################################
# HTML Serializer
###############################################################################

VOID_ELEMENTS_SET = VOID_ELEMENTS

# Characters that need to be escaped in attribute values
def escape_attr(val):
    """Escape attribute value - html5ever escapes &, ", NBSP"""
    val = val.replace('&', '&amp;')
    val = val.replace('"', '&quot;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def escape_text(val):
    """Escape text content"""
    val = val.replace('&', '&amp;')
    val = val.replace('<', '&lt;')
    val = val.replace('>', '&gt;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def needs_quoting(val):
    """Check if attribute value needs quoting per html5"""
    # html5ever serializes without quotes unless special chars present
    # Actually html5ever ALWAYS uses double quotes for attributes
    # Let me check: the output we saw was <div class="foo" data-x="1" id="bar">
    # YES - always quoted with double quotes
    return True  # Always quote in html5ever style

def serialize_node(node, output, indent=0, pretty=False):
    """Serialize a DOM node to HTML"""
    if node.node_type == Node.TEXT_NODE:
        if pretty:
            stripped = node.data.strip()
            if stripped:
                output.append(' ' * indent)
                output.append(escape_text(stripped))
                output.append('\n')
        else:
            output.append(escape_text(node.data))
    elif node.node_type == Node.COMMENT_NODE:
        output.append(f'<!--{node.data}-->')
    elif node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name

        if pretty:
            output.append(' ' * indent)

        output.append(f'<{tag}')

        # Sort attributes alphabetically (html5ever behavior)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            output.append(f' {attr_name}="{escape_attr(val)}"')

        output.append('>')

        if tag not in VOID_ELEMENTS_SET:
            if pretty:
                has_non_whitespace_children = any(
                    c.node_type == Node.ELEMENT_NODE or 
                    (c.node_type == Node.TEXT_NODE and c.data.strip())
                    for c in node.children
                )
                if has_non_whitespace_children:
                    output.append('\n')
                    for child in node.children:
                        serialize_node(child, output, indent + 2, pretty)
                    output.append(' ' * indent)
                output.append(f'</{tag}>')
                output.append('\n')
            else:
                for child in node.children:
                    serialize_node(child, output, indent, pretty)
                output.append(f'</{tag}>')
    elif node.node_type == Node.DOCUMENT_NODE:
        for child in node.children:
            serialize_node(child, output, indent, pretty)

def serialize_element(node, pretty=False):
    """Serialize a single element to HTML string"""
    output = []
    serialize_node(node, output, 0, pretty)
    return ''.join(output)

###############################################################################
# URL resolution
###############################################################################

def resolve_url(base_url, relative_url):
    """Resolve a URL relative to a base URL"""
    if not base_url:
        return relative_url

    # If already absolute, return as-is
    if '://' in relative_url or relative_url.startswith('//'):
        return relative_url

    # Parse base URL
    if '://' in base_url:
        scheme_end = base_url.index('://')
        scheme = base_url[:scheme_end]
        rest = base_url[scheme_end+3:]
        slash_pos = rest.find('/')
        if slash_pos == -1:
            host = rest
            path = '/'
        else:
            host = rest[:slash_pos]
            path = rest[slash_pos:]
    else:
        scheme = 'http'
        host = ''
        path = base_url

    if relative_url.startswith('/'):
        # Absolute path
        result_path = relative_url
    else:
        # Relative path
        # Get base directory
        last_slash = path.rfind('/')
        if last_slash != -1:
            base_dir = path[:last_slash + 1]
        else:
            base_dir = '/'

        result_path = base_dir + relative_url

    # Normalize path (resolve .. and .)
    parts = result_path.split('/')
    normalized = []
    for part in parts:
        if part == '..':
            if normalized:
                normalized.pop()
        elif part != '.':
            normalized.append(part)

    result_path = '/'.join(normalized)
    if not result_path.startswith('/'):
        result_path = '/' + result_path

    if host:
        return f'{scheme}://{host}{result_path}'
    else:
        return result_path

def get_base_url(doc, detect_base, base_url):
    """Get the base URL for resolving relative URLs"""
    if detect_base:
        # Look for <base href="..."> in the document
        def find_base(node):
            if node.node_type == Node.ELEMENT_NODE:
                if node.tag_name == 'base' and 'href' in node.attrs:
                    return node.attrs['href']
                for child in node.children:
                    result = find_base(child)
                    if result:
                        return result
            elif node.node_type == Node.DOCUMENT_NODE:
                for child in node.children:
                    result = find_base(child)
                    if result:
                        return result
            return None

        found = find_base(doc)
        if found:
            return found

    return base_url

###############################################################################
# Main logic
###############################################################################

def get_all_elements(node):
    """Get all elements in document order"""
    result = []
    def traverse(n):
        if n.node_type == Node.ELEMENT_NODE:
            result.append(n)
        if hasattr(n, 'children'):
            for child in n.children:
                traverse(child)
    traverse(node)
    return result

def remove_nodes(doc, selector_str):
    """Remove all nodes matching selector from the document"""
    try:
        sel = parse_selector(selector_str)
    except Exception:
        return

    # Find all matching nodes
    to_remove = sel.select(doc)

    # Remove them from their parents
    for node in to_remove:
        if node.parent:
            try:
                node.parent.children.remove(node)
            except ValueError:
                pass
            node.parent = None

def select_from_nodes(nodes, selector_str):
    """Select from a list of nodes (as roots)"""
    try:
        sel = parse_selector(selector_str)
    except Exception:
        return []

    results = []
    seen = set()

    for root in nodes:
        # Find all descendants matching the selector
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if sel.matches(node) and id(node) not in seen:
                    seen.add(id(node))
                    results.append(node)
                for child in node.children:
                    traverse(child)

        for child in root.children:
            traverse(child)

    return results

def get_text_nodes(element, ignore_whitespace=False):
    """Get all text content from an element"""
    texts = []

    def traverse(node):
        if node.node_type == Node.TEXT_NODE:
            if ignore_whitespace and not node.data.strip():
                return
            texts.append(node.data)
        elif node.node_type == Node.ELEMENT_NODE:
            for child in node.children:
                traverse(child)

    for child in element.children:
        traverse(child)

    return texts

def main():
    parser = argparse.ArgumentParser(
        prog='htmlq',
        description='Runs CSS selectors on HTML',
        add_help=False,
    )

    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-V', '--version', action='store_true')
    parser.add_argument('-B', '--detect-base', action='store_true')
    parser.add_argument('-w', '--ignore-whitespace', action='store_true')
    parser.add_argument('-p', '--pretty', action='store_true')
    parser.add_argument('-t', '--text', action='store_true')
    parser.add_argument('-a', '--attribute', default=None)
    parser.add_argument('-b', '--base', default=None)
    parser.add_argument('-f', '--filename', default=None, metavar='FILE')
    parser.add_argument('-o', '--output', default=None, metavar='FILE')
    parser.add_argument('-r', '--remove-nodes', action='append', default=None, metavar='SELECTOR')
    parser.add_argument('selector', nargs='*', default=['html'])

    args = parser.parse_args()

    if args.help:
        print("""htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    htmlq [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]""")
        return

    if args.version:
        print("htmlq 0.4.0")
        return

    # Read input
    if args.filename:
        with open(args.filename, 'r', encoding='utf-8', errors='replace') as f:
            html_input = f.read()
    else:
        html_input = sys.stdin.read()

    # Parse HTML
    doc = parse_html(html_input)

    # Remove nodes if requested
    if args.remove_nodes:
        for sel_str in args.remove_nodes:
            remove_nodes(doc, sel_str)

    # Get base URL
    base_url = get_base_url(doc, args.detect_base, args.base)

    # Open output file
    if args.output:
        out_file = open(args.output, 'w', encoding='utf-8')
    else:
        out_file = sys.stdout

    try:
        # Apply selectors
        selectors = args.selector

        # Start with all elements from document
        if not selectors:
            selectors = ['html']

        # Apply first selector to document
        first_selector = selectors[0]
        try:
            sel = parse_selector(first_selector)
        except Exception as e:
            print(f"Error parsing selector '{first_selector}': {e}", file=sys.stderr)
            return

        current_nodes = sel.select(doc)

        # Chain remaining selectors
        for selector_str in selectors[1:]:
            try:
                sel = parse_selector(selector_str)
            except Exception as e:
                print(f"Error parsing selector '{selector_str}': {e}", file=sys.stderr)
                return
            current_nodes = select_from_nodes(current_nodes, selector_str)

        # Output results
        for node in current_nodes:
            if args.text:
                texts = get_text_nodes(node, args.ignore_whitespace)
                for text in texts:
                    out_file.write(text)
                out_file.write('\n')
            elif args.attribute:
                val = node.get_attribute(args.attribute)
                if val is not None:
                    if base_url:
                        # Resolve relative URLs for href, src, action, etc.
                        val = resolve_url(base_url, val)
                    out_file.write(val)
                    out_file.write('\n')
            else:
                html_str = serialize_element(node, args.pretty)
                if args.pretty and not html_str.startswith('\n'):
                    out_file.write('\n')
                out_file.write(html_str)
                if not args.pretty:
                    out_file.write('\n')
    finally:
        if args.output:
            out_file.close()

if __name__ == '__main__':
    main()
