    'caption', 'col', 'colgroup', 'dd', 'details', 'dialog', 'div', 'dl', 'dt',
    'fieldset', 'figcaption', 'figure', 'footer', 'form',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header', 'hgroup', 'hr', 'html',
    'legend', 'li', 'main', 'menu', 'menuitem', 'nav', 'ol', 'p', 'pre',
    'section', 'source', 'style', 'summary', 'table', 'tbody', 'td', 'tfoot',
    'th', 'thead', 'title', 'tr', 'ul',
})

def escape_attr_val(val):
    """Escape attribute value for HTML serialization (html5ever style)"""
    val = val.replace('&', '&amp;')
    val = val.replace('"', '&quot;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def escape_text(val):
    """Escape text content for HTML serialization"""
    val = val.replace('&', '&amp;')
    val = val.replace('<', '&lt;')
    val = val.replace('>', '&gt;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def serialize_node_normal(node, buf):
    """Serialize a node (non-pretty mode)"""
    if node.node_type == Node.TEXT_NODE:
        buf.append(escape_text(node.data))
    elif node.node_type == Node.COMMENT_NODE:
        buf.append('<!--')
        buf.append(node.data)
        buf.append('-->')
    elif node.node_type == Node.DOCTYPE_NODE:
        buf.append('<!DOCTYPE ')
        buf.append(node.name)
        if node.public_id:
            buf.append(' PUBLIC "')
            buf.append(node.public_id)
            buf.append('"')
        if node.system_id:
            buf.append(' "')
            buf.append(node.system_id)
            buf.append('"')
        buf.append('>')
    elif node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')
        if tag not in VOID_ELEMENTS:
            for child in node.children:
                serialize_node_normal(child, buf)
            buf.append('</')
            buf.append(tag)
            buf.append('>')
    elif node.node_type == Node.DOCUMENT_NODE:
        for child in node.children:
            serialize_node_normal(child, buf)

def serialize_element_normal(node):
    """Serialize a single element (non-pretty mode) to string"""
    buf = []
    serialize_node_normal(node, buf)
    return ''.join(buf)

def serialize_node_pretty(node, indent, on_same_line, buf):
    """
    Serialize a node in pretty-print mode.

    Args:
        node: The node to serialize
        indent: Current indent level (number of 2-space units)
        on_same_line: Whether content starts inline with parent's opening tag
        buf: Output buffer (list of strings)

    Returns:
        New value of on_same_line for the next sibling
    """
    if node.node_type == Node.TEXT_NODE:
        text = escape_text(node.data)
        if on_same_line:
            buf.append(text)
        else:
            buf.append('\n')
            buf.append('  ' * indent)
            buf.append(text)
        return True  # after text, state is "inline"

    elif node.node_type == Node.COMMENT_NODE:
        if not on_same_line:
            buf.append('\n')
            buf.append('  ' * indent)
        buf.append('<!--')
        buf.append(node.data)
        buf.append('-->')
        return True

    elif node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        is_block = tag in BLOCK_ELEMENTS
        is_void = tag in VOID_ELEMENTS

        # Decide whether to add newline before this element
        if is_block:
            # Block elements always get a newline before them
            buf.append('\n')
            buf.append('  ' * indent)
        elif not on_same_line:
            # Inline element but not on same line (because prev sibling was block)
            buf.append('\n')
            buf.append('  ' * indent)
        # else: inline and on_same_line -> write tag inline (no newline)

        # Write start tag
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')

        if is_void:
            # Void element: no children, no closing tag
            if is_block:
                # After void block: add "\n" + indent (as "after block" marker)
                buf.append('\n')
                buf.append('  ' * indent)
                return False  # After block, on_same_line = False
            else:
                return True if on_same_line else False
        else:
            # Non-void: serialize children
            # Children start on_same_line based on the current state when we opened
            # (from parent's perspective)
            child_on_same_line = on_same_line  # inherit parent state

            child_indent = indent + 1 if is_block else indent

            for child in node.children:
                child_on_same_line = serialize_node_pretty(
                    child, child_indent, child_on_same_line, buf
                )

            # Closing tag
            if is_block:
                buf.append('\n')
                buf.append('  ' * indent)
                buf.append('</')
                buf.append(tag)
                buf.append('>')
                return False  # after block, on_same_line = False
            else:
                # Inline closing tag: right after content
                buf.append('</')
                buf.append(tag)
                buf.append('>')
                return True  # after inline, on_same_line stays True

    elif node.node_type == Node.DOCUMENT_NODE:
        for child in node.children:
            on_same_line = serialize_node_pretty(child, indent, on_same_line, buf)
        return on_same_line

    return on_same_line

def serialize_element_pretty(node):
    """Serialize a single element (pretty-print mode) to string"""
    buf = []

    # Root element always starts with "\n" prefix
    if node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        is_block = tag in BLOCK_ELEMENTS
        is_void = tag in VOID_ELEMENTS

        # Leading newline for root
        buf.append('\n')

        # Start tag
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')

        if not is_void:
            # Children start with on_same_line = True (inline with the root element)
            child_on_same_line = True
            child_indent = 1 if is_block else 0

            for child in node.children:
                child_on_same_line = serialize_node_pretty(
                    child, child_indent, child_on_same_line, buf
                )

            # Closing tag
            if is_block:
                buf.append('\n')
                buf.append('</')
                buf.append(tag)
                buf.append('>')
            else:
                buf.append('</')
                buf.append(tag)
                buf.append('>')

        buf.append('\n')
    else:
        # Document or other node type
        on_same_line = True
        for child in node.children:
            on_same_line = serialize_node_pretty(child, 0, on_same_line, buf)
        buf.append('\n')

    return ''.join(buf)

###############################################################################
# CSS Selector Engine
###############################################################################

class SelectorParser:
    def __init__(self, s):
        self.s = s.strip()
        self.pos = 0

    def parse(self):
        """Parse selector list (comma-separated)"""
        selectors = []
        self._skip_ws()
        while self.pos < len(self.s):
            sel = self._parse_complex()
            if sel is not None:
                selectors.append(sel)
            self._skip_ws()
            if self.pos < len(self.s) and self.s[self.pos] == ',':
                self.pos += 1
                self._skip_ws()
        if not selectors:
            return None
        if len(selectors) == 1:
            return selectors[0]
        return SelectorList(selectors)

    def _skip_ws(self):
        while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r\f':
            self.pos += 1

    def _parse_complex(self):
        """Parse complex selector (with combinators)"""
        left = self._parse_compound()
        if left is None:
            return None

        while self.pos < len(self.s):
            # Check for combinator
            saved = self.pos
            has_ws = False
            while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r\f':
                has_ws = True
                self.pos += 1

            if self.pos >= len(self.s) or self.s[self.pos] in (',',):
                # End of complex selector
                self.pos = saved if not has_ws else self.pos
                # But we've already consumed whitespace, need to handle comma case
                break

            c = self.s[self.pos]
            if c == '>':
                self.pos += 1
                self._skip_ws()
                combinator = '>'
            elif c == '+':
                self.pos += 1
                self._skip_ws()
                combinator = '+'
            elif c == '~':
                self.pos += 1
                self._skip_ws()
                combinator = '~'
            elif has_ws:
                combinator = ' '
            else:
                self.pos = saved
                break

            right = self._parse_compound()
            if right is None:
                self.pos = saved
                break
            left = CombinatorSelector(left, combinator, right)

        return left

    def _parse_compound(self):
        """Parse compound selector (multiple simple selectors)"""
        simples = []
        while self.pos < len(self.s):
            simple = self._parse_simple()
            if simple is None:
                break
            simples.append(simple)
        if not simples:
            return None
        if len(simples) == 1:
            return simples[0]
        return CompoundSelector(simples)

    def _parse_simple(self):
        """Parse one simple selector"""
        if self.pos >= len(self.s):
            return None
        c = self.s[self.pos]

        if c == '*':
            self.pos += 1
            return UniversalSelector()
        elif c == '#':
            self.pos += 1
            name = self._parse_ident()
            return IDSelector(name)
        elif c == '.':
            self.pos += 1
            name = self._parse_ident()
            return ClassSelector(name)
        elif c == '[':
            return self._parse_attr()
        elif c == ':':
            return self._parse_pseudo()
        elif self._is_ident_start(c):
            name = self._parse_ident()
            return TagSelector(name.lower())
        return None

    def _is_ident_start(self, c):
        return c.isalpha() or c == '_' or c == '-' or ord(c) > 127

    def _parse_ident(self):
        start = self.pos
        while self.pos < len(self.s):
            c = self.s[self.pos]
            if c.isalnum() or c in '_-' or ord(c) > 127:
                self.pos += 1
            else:
                break
        return self.s[start:self.pos]

    def _parse_attr(self):
        assert self.s[self.pos] == '['
        self.pos += 1
        self._skip_ws()
        name = self._parse_ident()
        self._skip_ws()

        if self.pos >= len(self.s) or self.s[self.pos] == ']':
            if self.pos < len(self.s):
                self.pos += 1
            return AttrSelector(name, None, None, False)

        # Operator
        op = ''
        if self.pos < len(self.s) and self.s[self.pos] in '=~^$*|':
            ch = self.s[self.pos]
            if ch == '=':
                op = '='
                self.pos += 1
            else:
                op = ch
                self.pos += 1
                if self.pos < len(self.s) and self.s[self.pos] == '=':
                    op += '='
                    self.pos += 1

        self._skip_ws()

        # Value
        val = ''
        case_insensitive = False
        if self.pos < len(self.s):
            if self.s[self.pos] in ('"', "'"):
                q = self.s[self.pos]
                self.pos += 1
                start = self.pos
                while self.pos < len(self.s) and self.s[self.pos] != q:
                    self.pos += 1
                val = self.s[start:self.pos]
                if self.pos < len(self.s):
                    self.pos += 1
            else:
                val = self._parse_ident()

        self._skip_ws()

        # Case insensitive modifier
        if self.pos < len(self.s) and self.s[self.pos].lower() == 'i':
            case_insensitive = True
            self.pos += 1
            self._skip_ws()

        if self.pos < len(self.s) and self.s[self.pos] == ']':
            self.pos += 1

        return AttrSelector(name, op, val, case_insensitive)

    def _parse_pseudo(self):
        assert self.s[self.pos] == ':'
        self.pos += 1
        if self.pos < len(self.s) and self.s[self.pos] == ':':
            self.pos += 1  # ::pseudo-element
        name = self._parse_ident()

        arg = None
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1
            depth = 1
            start = self.pos
            while self.pos < len(self.s) and depth > 0:
                if self.s[self.pos] == '(':
                    depth += 1
                elif self.s[self.pos] == ')':
                    depth -= 1
                self.pos += 1
            arg = self.s[start:self.pos-1]

        return PseudoSelector(name.lower(), arg)


def parse_selector(s):
    return SelectorParser(s).parse()


class SelectorList:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, elem):
        return any(s.matches(elem) for s in self.selectors)

    def select(self, root):
        seen = set()
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if self.matches(node) and id(node) not in seen:
                    seen.add(id(node))
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class UniversalSelector:
    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class TagSelector:
    def __init__(self, tag):
        self.tag = tag.lower()

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and elem.tag_name == self.tag

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if node.tag_name == self.tag:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class IDSelector:
    def __init__(self, id_val):
        self.id_val = id_val

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and elem.id == self.id_val

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if node.id == self.id_val:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class ClassSelector:
    def __init__(self, cls):
        self.cls = cls

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and self.cls in elem.classes

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if self.cls in node.classes:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class AttrSelector:
    def __init__(self, attr, op, value, case_insensitive=False):
        self.attr = attr.lower()
        self.op = op
        self.value = value
        self.ci = case_insensitive

    def matches(self, elem):
        if elem.node_type != Node.ELEMENT_NODE:
            return False
        if not elem.has_attribute(self.attr):
            return False
        if self.op is None:
            return True

        val = elem.get_attribute(self.attr) or ''
        expected = self.value

        if self.ci:
            val = val.lower()
            expected = expected.lower()

        if self.op == '=':
            return val == expected
        elif self.op == '~=':
            return expected in val.split()
        elif self.op == '^=':
            return expected and val.startswith(expected)
        elif self.op == '$=':
            return expected and val.endswith(expected)
        elif self.op == '*=':
            return expected in val
        elif self.op == '|=':
            return val == expected or val.startswith(expected + '-')
        return False

class PseudoSelector:
    def __init__(self, name, arg):
        self.name = name
        self.arg = arg

    def _elem_siblings(self, elem):
        if not elem.parent:
            return []
        return [c for c in elem.parent.children if c.node_type == Node.ELEMENT_NODE]

    def _type_siblings(self, elem):
        if not elem.parent:
            return []
        return [c for c in elem.parent.children 
                if c.node_type == Node.ELEMENT_NODE and c.tag_name == elem.tag_name]

    def _parse_nth(self, arg):
        arg = (arg or '').strip().lower()
        if arg == 'odd':
            return (2, 1)
        elif arg == 'even':
            return (2, 0)
        m = re.match(r'^([+-]?\d+)?n\s*([+-]\s*\d+)?$', arg)
        if m:
            a = int(m.group(1)) if m.group(1) else 1
            b_str = m.group(2)
            if b_str:
                b = int(b_str.replace(' ', ''))
            else:
                b = 0
            return (a, b)
        m = re.match(r'^([+-]?\d+)$', arg)
        if m:
            return (0, int(m.group(1)))
        return (0, 0)

    def _nth_match(self, n, a, b):
        if a == 0:
            return n == b
        return (n - b) % a == 0 and (n - b) // a >= 0

    def matches(self, elem):
        if elem.node_type != Node.ELEMENT_NODE:
            return False
        n = self.name

        if n == 'first-child':
            sibs = self._elem_siblings(elem)
            return bool(sibs) and sibs[0] is elem
        elif n == 'last-child':
            sibs = self._elem_siblings(elem)
            return bool(sibs) and sibs[-1] is elem
        elif n == 'first-of-type':
            sibs = self._type_siblings(elem)
            return bool(sibs) and sibs[0] is elem
        elif n == 'last-of-type':
            sibs = self._type_siblings(elem)
            return bool(sibs) and sibs[-1] is elem
        elif n == 'only-child':
            sibs = self._elem_siblings(elem)
            return len(sibs) == 1 and sibs[0] is elem
        elif n == 'only-of-type':
            sibs = self._type_siblings(elem)
            return len(sibs) == 1 and sibs[0] is elem
        elif n == 'nth-child':
            sibs = self._elem_siblings(elem)
            for i, s in enumerate(sibs):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-last-child':
            sibs = self._elem_siblings(elem)
            for i, s in enumerate(reversed(sibs)):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-of-type':
            sibs = self._type_siblings(elem)
            for i, s in enumerate(sibs):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-last-of-type':
            sibs = self._type_siblings(elem)
            for i, s in enumerate(reversed(sibs)):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'root':
            return elem.parent is not None and elem.parent.node_type == Node.DOCUMENT_NODE
        elif n == 'not':
            try:
                sub = parse_selector(self.arg)
                return sub is not None and not sub.matches(elem)
            except Exception:
                return True
        elif n == 'empty':
            return not any(
                c.node_type == Node.ELEMENT_NODE or
                (c.node_type == Node.TEXT_NODE and c.data.strip())
                for c in elem.children
            )
        elif n in ('link', 'visited', 'hover', 'active', 'focus', 'checked',
                   'enabled', 'disabled', 'target', 'lang'):
            return False
        # Unknown pseudo-classes: return False
        return False

class CompoundSelector:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, elem):
        return all(s.matches(elem) for s in self.selectors)

class CombinatorSelector:
    def __init__(self, left, combinator, right):
        self.left = left
        self.combinator = combinator
        self.right = right

    def matches(self, elem):
        if not self.right.matches(elem):
            return False

        if self.combinator == ' ':
            anc = elem.parent
            while anc:
                if self.left.matches(anc):
                    return True
                anc = anc.parent
            return False
        elif self.combinator == '>':
            return elem.parent is not None and self.left.matches(elem.parent)
        elif self.combinator == '+':
            if not elem.parent:
                return False
            prev_elem = None
            for child in elem.parent.children:
                if child is elem:
                    return prev_elem is not None and self.left.matches(prev_elem)
                if child.node_type == Node.ELEMENT_NODE:
                    prev_elem = child
            return False
        elif self.combinator == '~':
            if not elem.parent:
                return False
            for child in elem.parent.children:
                if child is elem:
                    return False
                if child.node_type == Node.ELEMENT_NODE and self.left.matches(child):
                    # Check that elem comes after this child
                    found_left = False
                    for c2 in elem.parent.children:
                        if c2 is child:
                            found_left = True
                        elif c2 is elem and found_left:
                            return True
            return False
        return False

def do_select(selector_or_str, root):
    """Select all matching elements from root"""
    if isinstance(selector_or_str, str):
        sel = parse_selector(selector_or_str)
    else:
        sel = selector_or_str

    if sel is None:
        return []

    seen = set()
    results = []

    def traverse(node):
        if node.node_type == Node.ELEMENT_NODE:
            if sel.matches(node) and id(node) not in seen:
                seen.add(id(node))
                results.append(node)
            for child in node.children:
                traverse(child)
        elif hasattr(node, 'children'):
            for child in node.children:
                traverse(child)

    traverse(root)
    return results

def do_select_within(selector_str, parent_nodes):
    """Select matching elements within given parent nodes (not including parents themselves)"""
    sel = parse_selector(selector_str)
    if sel is None:
        return []

    seen = set()
    results = []

    def traverse(node):
        if node.node_type == Node.ELEMENT_NODE:
            if sel.matches(node) and id(node) not in seen:
                seen.add(id(node))
                results.append(node)
            for child in node.children:
                traverse(child)

    for parent in parent_nodes:
        for child in parent.children:
            traverse(child)

    return results

###############################################################################
# Node removal
###############################################################################

def remove_matching_nodes(doc, selector_str):
    """Remove all nodes matching selector from the document"""
    sel = parse_selector(selector_str)
    if sel is None:
        return

    to_remove = do_select(sel, doc)
    for node in to_remove:
        if node.parent:
            try:
                node.parent.children.remove(node)
            except ValueError:
                pass
            node.parent = None

