def resolve_url(base, url):
    """Resolve URL relative to base"""
    if not base or not url:
        return url

    # Already absolute
    if re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*://', url) or url.startswith('//'):
        return url

    # Parse base
    m = re.match(r'^([a-zA-Z][a-zA-Z0-9+\-.]*)://([^/]*)(.*)', base)
    if m:
        scheme = m.group(1)
        host = m.group(2)
        path = m.group(3) or '/'
    else:
        scheme = 'http'
        host = ''
        path = base

    if url.startswith('/'):
        result_path = url
    elif url.startswith('#') or url.startswith('?'):
        # Fragment or query - relative to current path
        result_path = path.split('?')[0].split('#')[0] + url
    else:
        # Relative path
        slash_pos = path.rfind('/')
        base_dir = path[:slash_pos + 1] if slash_pos >= 0 else '/'
        result_path = base_dir + url

    # Normalize path
    parts = result_path.split('/')
    normalized = []
    for part in parts:
        if part == '..':
            if normalized and normalized[-1] != '':
                normalized.pop()
        elif part != '.':
            normalized.append(part)
    result_path = '/'.join(normalized)
    if not result_path.startswith('/'):
        result_path = '/' + result_path

    if host:
        return f'{scheme}://{host}{result_path}'
    return result_path

def detect_base_url(doc):
    """Find <base href="..."> in the document"""
    def find(node):
        if node.node_type == Node.ELEMENT_NODE:
            if node.tag_name == 'base' and 'href' in node.attrs:
                return node.attrs['href']
            for child in node.children:
                r = find(child)
                if r:
                    return r
        elif hasattr(node, 'children'):
            for child in node.children:
                r = find(child)
                if r:
                    return r
        return None
    return find(doc)

###############################################################################
# Text extraction
###############################################################################

def get_text_nodes_all(elem):
    """Get all text nodes recursively (in order)"""
    result = []
    def traverse(node):
        if node.node_type == Node.TEXT_NODE:
            result.append(node.data)
        elif node.node_type == Node.ELEMENT_NODE:
            for child in node.children:
                traverse(child)
    for child in elem.children:
        traverse(child)
    return result

###############################################################################
# Main
###############################################################################

HELP_TEXT = """\
