class Node:
    ELEMENT_NODE = 1
    TEXT_NODE = 3
    COMMENT_NODE = 8
    DOCUMENT_NODE = 9
    DOCTYPE_NODE = 10

class Document(Node):
    def __init__(self):
        self.node_type = Node.DOCUMENT_NODE
        self.children = []
        self.parent = None

class Element(Node):
    __slots__ = ['node_type', 'tag_name', 'attrs', 'children', 'parent', '_id', '_classes']

    def __init__(self, tag_name, attrs=None, parent=None):
        self.node_type = Node.ELEMENT_NODE
        self.tag_name = tag_name.lower()
        self.attrs = attrs or {}
        self.children = []
        self.parent = parent
        self._id = None
        self._classes = None

    @property
    def id(self):
        if self._id is None:
            self._id = self.attrs.get('id', '')
        return self._id

    @property
    def classes(self):
        if self._classes is None:
            cls = self.attrs.get('class', '')
            self._classes = set(cls.split()) if cls else set()
        return self._classes

    def get_attribute(self, name):
        return self.attrs.get(name.lower())

    def has_attribute(self, name):
        return name.lower() in self.attrs

class TextNode(Node):
    __slots__ = ['node_type', 'data', 'parent', 'children']

    def __init__(self, data, parent=None):
        self.node_type = Node.TEXT_NODE
        self.data = data
        self.parent = parent
        self.children = []

class CommentNode(Node):
    __slots__ = ['node_type', 'data', 'parent', 'children']

    def __init__(self, data, parent=None):
        self.node_type = Node.COMMENT_NODE
        self.data = data
        self.parent = parent
        self.children = []

class DoctypeNode(Node):
    __slots__ = ['node_type', 'name', 'public_id', 'system_id', 'parent', 'children']

    def __init__(self, name, public_id, system_id, parent=None):
        self.node_type = Node.DOCTYPE_NODE
        self.name = name
        self.public_id = public_id or ''
        self.system_id = system_id or ''
        self.parent = parent
        self.children = []

###############################################################################
# HTML5 Parser using html5lib
###############################################################################

def build_dom_from_h5lib(h5node, parent=None):
    """Recursively build our DOM from html5lib's minidom"""
    import xml.dom.minidom as minidom

    if h5node.nodeType == minidom.Node.DOCUMENT_NODE:
        doc = Document()
        for child in h5node.childNodes:
            child_node = build_dom_from_h5lib(child, doc)
            if child_node is not None:
                doc.children.append(child_node)
                child_node.parent = doc
        return doc
    elif h5node.nodeType == minidom.Node.ELEMENT_NODE:
        tag = h5node.tagName
        if ':' in tag:
            tag = tag.split(':', 1)[1]
        tag = tag.lower()

        attrs = {}
        for i in range(h5node.attributes.length):
            attr = h5node.attributes.item(i)
            name = attr.name
            if ':' in name:
                name = name.split(':', 1)[1]
            attrs[name.lower()] = attr.value

        elem = Element(tag, attrs, parent)
        for child in h5node.childNodes:
            child_node = build_dom_from_h5lib(child, elem)
            if child_node is not None:
                elem.children.append(child_node)
                child_node.parent = elem
        return elem
    elif h5node.nodeType == minidom.Node.TEXT_NODE:
        return TextNode(h5node.data, parent)
    elif h5node.nodeType == minidom.Node.COMMENT_NODE:
        return CommentNode(h5node.data, parent)
    elif h5node.nodeType == minidom.Node.DOCUMENT_TYPE_NODE:
        return DoctypeNode(h5node.name, h5node.publicId, h5node.systemId, parent)
    return None

def parse_html(html_input):
    """Parse HTML using html5lib and return our DOM"""
    dom = html5lib.parse(html_input, treebuilder='dom')
    return build_dom_from_h5lib(dom)

###############################################################################
# HTML Serializer
###############################################################################

VOID_ELEMENTS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr',
})

# Block-level elements for pretty printing
# Based on html5ever's serialize behavior
BLOCK_ELEMENTS = frozenset({
    'address', 'article', 'aside', 'blockquote', 'body',
    'caption', 'col', 'colgroup', 'dd', 'details', 'dialog', 'div', 'dl', 'dt',
    'fieldset', 'figcaption', 'figure', 'footer', 'form',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header', 'hgroup', 'hr', 'html',
    'legend', 'li', 'main', 'menu', 'menuitem', 'nav', 'ol', 'p', 'pre',
    'section', 'source', 'style', 'summary', 'table', 'tbody', 'td', 'tfoot',
    'th', 'thead', 'title', 'tr', 'ul',
})

def escape_attr_val(val):
    """Escape attribute value for HTML serialization (html5ever style)"""
    val = val.replace('&', '&amp;')
    val = val.replace('"', '&quot;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def escape_text(val):
    """Escape text content for HTML serialization"""
    val = val.replace('&', '&amp;')
    val = val.replace('<', '&lt;')
    val = val.replace('>', '&gt;')
    val = val.replace('\u00a0', '&nbsp;')
    return val

def serialize_node_normal(node, buf):
    """Serialize a node (non-pretty mode)"""
    if node.node_type == Node.TEXT_NODE:
        buf.append(escape_text(node.data))
    elif node.node_type == Node.COMMENT_NODE:
        buf.append('<!--')
        buf.append(node.data)
        buf.append('-->')
    elif node.node_type == Node.DOCTYPE_NODE:
        buf.append('<!DOCTYPE ')
        buf.append(node.name)
        if node.public_id:
            buf.append(' PUBLIC "')
            buf.append(node.public_id)
            buf.append('"')
        if node.system_id:
            buf.append(' "')
            buf.append(node.system_id)
            buf.append('"')
        buf.append('>')
    elif node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')
        if tag not in VOID_ELEMENTS:
            for child in node.children:
                serialize_node_normal(child, buf)
            buf.append('</')
            buf.append(tag)
            buf.append('>')
    elif node.node_type == Node.DOCUMENT_NODE:
        for child in node.children:
            serialize_node_normal(child, buf)

def serialize_element_normal(node):
    """Serialize a single element (non-pretty mode) to string"""
    buf = []
    serialize_node_normal(node, buf)
    return ''.join(buf)

def serialize_node_pretty(node, indent, on_same_line, buf):
    """
    Serialize a node in pretty-print mode.

    Args:
        node: The node to serialize
        indent: Current indent level (number of 2-space units)
        on_same_line: Whether content starts inline with parent's opening tag
        buf: Output buffer (list of strings)

    Returns:
        New value of on_same_line for the next sibling
    """
    if node.node_type == Node.TEXT_NODE:
        text = escape_text(node.data)
        if on_same_line:
            buf.append(text)
        else:
            buf.append('\n')
            buf.append('  ' * indent)
            buf.append(text)
        return True  # after text, state is "inline"

    elif node.node_type == Node.COMMENT_NODE:
        if not on_same_line:
            buf.append('\n')
            buf.append('  ' * indent)
        buf.append('<!--')
        buf.append(node.data)
        buf.append('-->')
        return True

    elif node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        is_block = tag in BLOCK_ELEMENTS
        is_void = tag in VOID_ELEMENTS

        # Decide whether to add newline before this element
        if is_block:
            # Block elements always get a newline before them
            buf.append('\n')
            buf.append('  ' * indent)
        elif not on_same_line:
            # Inline element but not on same line (because prev sibling was block)
            buf.append('\n')
            buf.append('  ' * indent)
        # else: inline and on_same_line -> write tag inline (no newline)

        # Write start tag
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')

        if is_void:
            # Void element: no children, no closing tag
            if is_block:
                # After void block: add "\n" + indent (as "after block" marker)
                buf.append('\n')
                buf.append('  ' * indent)
                return False  # After block, on_same_line = False
            else:
                return True if on_same_line else False
        else:
            # Non-void: serialize children
            # Children start on_same_line based on the current state when we opened
            # (from parent's perspective)
            child_on_same_line = on_same_line  # inherit parent state

            child_indent = indent + 1 if is_block else indent

            for child in node.children:
                child_on_same_line = serialize_node_pretty(
                    child, child_indent, child_on_same_line, buf
                )

            # Closing tag
            if is_block:
                buf.append('\n')
                buf.append('  ' * indent)
                buf.append('</')
                buf.append(tag)
                buf.append('>')
                return False  # after block, on_same_line = False
            else:
                # Inline closing tag: right after content
                buf.append('</')
                buf.append(tag)
                buf.append('>')
                return True  # after inline, on_same_line stays True

    elif node.node_type == Node.DOCUMENT_NODE:
        for child in node.children:
            on_same_line = serialize_node_pretty(child, indent, on_same_line, buf)
        return on_same_line

    return on_same_line

def serialize_element_pretty(node):
    """Serialize a single element (pretty-print mode) to string"""
    buf = []

    # Root element always starts with "\n" prefix
    if node.node_type == Node.ELEMENT_NODE:
        tag = node.tag_name
        is_block = tag in BLOCK_ELEMENTS
        is_void = tag in VOID_ELEMENTS

        # Leading newline for root
        buf.append('\n')

        # Start tag
        buf.append('<')
        buf.append(tag)
        for attr_name in sorted(node.attrs.keys()):
            val = node.attrs[attr_name]
            buf.append(' ')
            buf.append(attr_name)
            buf.append('="')
            buf.append(escape_attr_val(val))
            buf.append('"')
        buf.append('>')

        if not is_void:
            # Children start with on_same_line = True (inline with the root element)
            child_on_same_line = True
            child_indent = 1 if is_block else 0

            for child in node.children:
                child_on_same_line = serialize_node_pretty(
                    child, child_indent, child_on_same_line, buf
                )

            # Closing tag
            if is_block:
                buf.append('\n')
                buf.append('</')
                buf.append(tag)
                buf.append('>')
            else:
                buf.append('</')
                buf.append(tag)
                buf.append('>')

        buf.append('\n')
    else:
        # Document or other node type
        on_same_line = True
        for child in node.children:
            on_same_line = serialize_node_pretty(child, 0, on_same_line, buf)
        buf.append('\n')

    return ''.join(buf)

###############################################################################
# CSS Selector Engine
###############################################################################

class SelectorParser:
    def __init__(self, s):
        self.s = s.strip()
        self.pos = 0

    def parse(self):
        """Parse selector list (comma-separated)"""
        selectors = []
        self._skip_ws()
        while self.pos < len(self.s):
            sel = self._parse_complex()
            if sel is not None:
                selectors.append(sel)
            self._skip_ws()
            if self.pos < len(self.s) and self.s[self.pos] == ',':
                self.pos += 1
                self._skip_ws()
        if not selectors:
            return None
        if len(selectors) == 1:
            return selectors[0]
        return SelectorList(selectors)

    def _skip_ws(self):
        while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r\f':
            self.pos += 1

    def _parse_complex(self):
        """Parse complex selector (with combinators)"""
        left = self._parse_compound()
        if left is None:
            return None

        while self.pos < len(self.s):
            # Check for combinator
            saved = self.pos
            has_ws = False
            while self.pos < len(self.s) and self.s[self.pos] in ' \t\n\r\f':
                has_ws = True
                self.pos += 1

            if self.pos >= len(self.s) or self.s[self.pos] in (',',):
                # End of complex selector
                self.pos = saved if not has_ws else self.pos
                # But we've already consumed whitespace, need to handle comma case
                break

            c = self.s[self.pos]
            if c == '>':
                self.pos += 1
                self._skip_ws()
                combinator = '>'
            elif c == '+':
                self.pos += 1
                self._skip_ws()
                combinator = '+'
            elif c == '~':
                self.pos += 1
                self._skip_ws()
                combinator = '~'
            elif has_ws:
                combinator = ' '
            else:
                self.pos = saved
                break

            right = self._parse_compound()
            if right is None:
                self.pos = saved
                break
            left = CombinatorSelector(left, combinator, right)

        return left

    def _parse_compound(self):
        """Parse compound selector (multiple simple selectors)"""
        simples = []
        while self.pos < len(self.s):
            simple = self._parse_simple()
            if simple is None:
                break
            simples.append(simple)
        if not simples:
            return None
        if len(simples) == 1:
            return simples[0]
        return CompoundSelector(simples)

    def _parse_simple(self):
        """Parse one simple selector"""
        if self.pos >= len(self.s):
            return None
        c = self.s[self.pos]

        if c == '*':
            self.pos += 1
            return UniversalSelector()
        elif c == '#':
            self.pos += 1
            name = self._parse_ident()
            return IDSelector(name)
        elif c == '.':
            self.pos += 1
            name = self._parse_ident()
            return ClassSelector(name)
        elif c == '[':
            return self._parse_attr()
        elif c == ':':
            return self._parse_pseudo()
        elif self._is_ident_start(c):
            name = self._parse_ident()
            return TagSelector(name.lower())
        return None

    def _is_ident_start(self, c):
        return c.isalpha() or c == '_' or c == '-' or ord(c) > 127

    def _parse_ident(self):
        start = self.pos
        while self.pos < len(self.s):
            c = self.s[self.pos]
            if c.isalnum() or c in '_-' or ord(c) > 127:
                self.pos += 1
            else:
                break
        return self.s[start:self.pos]

    def _parse_attr(self):
        assert self.s[self.pos] == '['
        self.pos += 1
        self._skip_ws()
        name = self._parse_ident()
        self._skip_ws()

        if self.pos >= len(self.s) or self.s[self.pos] == ']':
            if self.pos < len(self.s):
                self.pos += 1
            return AttrSelector(name, None, None, False)

        # Operator
        op = ''
        if self.pos < len(self.s) and self.s[self.pos] in '=~^$*|':
            ch = self.s[self.pos]
            if ch == '=':
                op = '='
                self.pos += 1
            else:
                op = ch
                self.pos += 1
                if self.pos < len(self.s) and self.s[self.pos] == '=':
                    op += '='
                    self.pos += 1

        self._skip_ws()

        # Value
        val = ''
        case_insensitive = False
        if self.pos < len(self.s):
            if self.s[self.pos] in ('"', "'"):
                q = self.s[self.pos]
                self.pos += 1
                start = self.pos
                while self.pos < len(self.s) and self.s[self.pos] != q:
                    self.pos += 1
                val = self.s[start:self.pos]
                if self.pos < len(self.s):
                    self.pos += 1
            else:
                val = self._parse_ident()

        self._skip_ws()

        # Case insensitive modifier
        if self.pos < len(self.s) and self.s[self.pos].lower() == 'i':
            case_insensitive = True
            self.pos += 1
            self._skip_ws()

        if self.pos < len(self.s) and self.s[self.pos] == ']':
            self.pos += 1

        return AttrSelector(name, op, val, case_insensitive)

    def _parse_pseudo(self):
        assert self.s[self.pos] == ':'
        self.pos += 1
        if self.pos < len(self.s) and self.s[self.pos] == ':':
            self.pos += 1  # ::pseudo-element
        name = self._parse_ident()

        arg = None
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1
            depth = 1
            start = self.pos
            while self.pos < len(self.s) and depth > 0:
                if self.s[self.pos] == '(':
                    depth += 1
                elif self.s[self.pos] == ')':
                    depth -= 1
                self.pos += 1
            arg = self.s[start:self.pos-1]

        return PseudoSelector(name.lower(), arg)


def parse_selector(s):
    return SelectorParser(s).parse()


class SelectorList:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, elem):
        return any(s.matches(elem) for s in self.selectors)

    def select(self, root):
        seen = set()
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if self.matches(node) and id(node) not in seen:
                    seen.add(id(node))
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class UniversalSelector:
    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class TagSelector:
    def __init__(self, tag):
        self.tag = tag.lower()

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and elem.tag_name == self.tag

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if node.tag_name == self.tag:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class IDSelector:
    def __init__(self, id_val):
        self.id_val = id_val

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and elem.id == self.id_val

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if node.id == self.id_val:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class ClassSelector:
    def __init__(self, cls):
        self.cls = cls

    def matches(self, elem):
        return elem.node_type == Node.ELEMENT_NODE and self.cls in elem.classes

    def select(self, root):
        results = []
        def traverse(node):
            if node.node_type == Node.ELEMENT_NODE:
                if self.cls in node.classes:
                    results.append(node)
                for child in node.children:
                    traverse(child)
            elif hasattr(node, 'children'):
                for child in node.children:
                    traverse(child)
        traverse(root)
        return results

class AttrSelector:
    def __init__(self, attr, op, value, case_insensitive=False):
        self.attr = attr.lower()
        self.op = op
        self.value = value
        self.ci = case_insensitive

    def matches(self, elem):
        if elem.node_type != Node.ELEMENT_NODE:
            return False
        if not elem.has_attribute(self.attr):
            return False
        if self.op is None:
            return True

        val = elem.get_attribute(self.attr) or ''
        expected = self.value

        if self.ci:
            val = val.lower()
            expected = expected.lower()

        if self.op == '=':
            return val == expected
        elif self.op == '~=':
            return expected in val.split()
        elif self.op == '^=':
            return expected and val.startswith(expected)
        elif self.op == '$=':
            return expected and val.endswith(expected)
        elif self.op == '*=':
            return expected in val
        elif self.op == '|=':
            return val == expected or val.startswith(expected + '-')
        return False

class PseudoSelector:
    def __init__(self, name, arg):
        self.name = name
        self.arg = arg

    def _elem_siblings(self, elem):
        if not elem.parent:
            return []
        return [c for c in elem.parent.children if c.node_type == Node.ELEMENT_NODE]

    def _type_siblings(self, elem):
        if not elem.parent:
            return []
        return [c for c in elem.parent.children 
                if c.node_type == Node.ELEMENT_NODE and c.tag_name == elem.tag_name]

    def _parse_nth(self, arg):
        arg = (arg or '').strip().lower()
        if arg == 'odd':
            return (2, 1)
        elif arg == 'even':
            return (2, 0)
        m = re.match(r'^([+-]?\d+)?n\s*([+-]\s*\d+)?$', arg)
        if m:
            a = int(m.group(1)) if m.group(1) else 1
            b_str = m.group(2)
            if b_str:
                b = int(b_str.replace(' ', ''))
            else:
                b = 0
            return (a, b)
        m = re.match(r'^([+-]?\d+)$', arg)
        if m:
            return (0, int(m.group(1)))
        return (0, 0)

    def _nth_match(self, n, a, b):
        if a == 0:
            return n == b
        return (n - b) % a == 0 and (n - b) // a >= 0

    def matches(self, elem):
        if elem.node_type != Node.ELEMENT_NODE:
            return False
        n = self.name

        if n == 'first-child':
            sibs = self._elem_siblings(elem)
            return bool(sibs) and sibs[0] is elem
        elif n == 'last-child':
            sibs = self._elem_siblings(elem)
            return bool(sibs) and sibs[-1] is elem
        elif n == 'first-of-type':
            sibs = self._type_siblings(elem)
            return bool(sibs) and sibs[0] is elem
        elif n == 'last-of-type':
            sibs = self._type_siblings(elem)
            return bool(sibs) and sibs[-1] is elem
        elif n == 'only-child':
            sibs = self._elem_siblings(elem)
            return len(sibs) == 1 and sibs[0] is elem
        elif n == 'only-of-type':
            sibs = self._type_siblings(elem)
            return len(sibs) == 1 and sibs[0] is elem
        elif n == 'nth-child':
            sibs = self._elem_siblings(elem)
            for i, s in enumerate(sibs):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-last-child':
            sibs = self._elem_siblings(elem)
            for i, s in enumerate(reversed(sibs)):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-of-type':
            sibs = self._type_siblings(elem)
            for i, s in enumerate(sibs):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'nth-last-of-type':
            sibs = self._type_siblings(elem)
            for i, s in enumerate(reversed(sibs)):
                if s is elem:
                    a, b = self._parse_nth(self.arg)
                    return self._nth_match(i + 1, a, b)
            return False
        elif n == 'root':
            return elem.parent is not None and elem.parent.node_type == Node.DOCUMENT_NODE
        elif n == 'not':
            try:
                sub = parse_selector(self.arg)
                return sub is not None and not sub.matches(elem)
            except Exception:
                return True
        elif n == 'empty':
            return not any(
                c.node_type == Node.ELEMENT_NODE or
                (c.node_type == Node.TEXT_NODE and c.data.strip())
                for c in elem.children
            )
        elif n in ('link', 'visited', 'hover', 'active', 'focus', 'checked',
                   'enabled', 'disabled', 'target', 'lang'):
            return False
        # Unknown pseudo-classes: return False
        return False

class CompoundSelector:
    def __init__(self, selectors):
        self.selectors = selectors

    def matches(self, elem):
        return all(s.matches(elem) for s in self.selectors)

class CombinatorSelector:
    def __init__(self, left, combinator, right):
        self.left = left
        self.combinator = combinator
        self.right = right

    def matches(self, elem):
        if not self.right.matches(elem):
            return False

        if self.combinator == ' ':
            anc = elem.parent
            while anc:
                if self.left.matches(anc):
                    return True
                anc = anc.parent
            return False
        elif self.combinator == '>':
            return elem.parent is not None and self.left.matches(elem.parent)
        elif self.combinator == '+':
            if not elem.parent:
                return False
            prev_elem = None
            for child in elem.parent.children:
                if child is elem:
                    return prev_elem is not None and self.left.matches(prev_elem)
                if child.node_type == Node.ELEMENT_NODE:
                    prev_elem = child
            return False
        elif self.combinator == '~':
            if not elem.parent:
                return False
            for child in elem.parent.children:
                if child is elem:
                    return False
                if child.node_type == Node.ELEMENT_NODE and self.left.matches(child):
                    # Check that elem comes after this child
                    found_left = False
                    for c2 in elem.parent.children:
                        if c2 is child:
                            found_left = True
                        elif c2 is elem and found_left:
                            return True
            return False
        return False

def do_select(selector_or_str, root):
    """Select all matching elements from root"""
    if isinstance(selector_or_str, str):
        sel = parse_selector(selector_or_str)
    else:
        sel = selector_or_str

    if sel is None:
        return []

    seen = set()
    results = []

    def traverse(node):
        if node.node_type == Node.ELEMENT_NODE:
            if sel.matches(node) and id(node) not in seen:
                seen.add(id(node))
                results.append(node)
            for child in node.children:
                traverse(child)
        elif hasattr(node, 'children'):
            for child in node.children:
                traverse(child)

    traverse(root)
    return results

def do_select_within(selector_str, parent_nodes):
    """Select matching elements within given parent nodes (not including parents themselves)"""
    sel = parse_selector(selector_str)
    if sel is None:
        return []

    seen = set()
    results = []

    def traverse(node):
        if node.node_type == Node.ELEMENT_NODE:
            if sel.matches(node) and id(node) not in seen:
                seen.add(id(node))
                results.append(node)
            for child in node.children:
                traverse(child)

    for parent in parent_nodes:
        for child in parent.children:
            traverse(child)

    return results

###############################################################################
# Node removal
###############################################################################

def remove_matching_nodes(doc, selector_str):
    """Remove all nodes matching selector from the document"""
    sel = parse_selector(selector_str)
    if sel is None:
        return

    to_remove = do_select(sel, doc)
    for node in to_remove:
        if node.parent:
            try:
                node.parent.children.remove(node)
            except ValueError:
                pass
            node.parent = None

###############################################################################
# URL resolution
###############################################################################

def resolve_url(base, url):
    """Resolve URL relative to base"""
    if not base or not url:
        return url

    # Already absolute
    if re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*://', url) or url.startswith('//'):
        return url

    # Parse base
    m = re.match(r'^([a-zA-Z][a-zA-Z0-9+\-.]*)://([^/]*)(.*)', base)
    if m:
        scheme = m.group(1)
        host = m.group(2)
        path = m.group(3) or '/'
    else:
        scheme = 'http'
        host = ''
        path = base

    if url.startswith('/'):
        result_path = url
    elif url.startswith('#') or url.startswith('?'):
        # Fragment or query - relative to current path
        result_path = path.split('?')[0].split('#')[0] + url
    else:
        # Relative path
        slash_pos = path.rfind('/')
        base_dir = path[:slash_pos + 1] if slash_pos >= 0 else '/'
        result_path = base_dir + url

    # Normalize path
    parts = result_path.split('/')
    normalized = []
    for part in parts:
        if part == '..':
            if normalized and normalized[-1] != '':
                normalized.pop()
        elif part != '.':
            normalized.append(part)
    result_path = '/'.join(normalized)
    if not result_path.startswith('/'):
        result_path = '/' + result_path

    if host:
        return f'{scheme}://{host}{result_path}'
    return result_path

def detect_base_url(doc):
    """Find <base href="..."> in the document"""
    def find(node):
        if node.node_type == Node.ELEMENT_NODE:
            if node.tag_name == 'base' and 'href' in node.attrs:
                return node.attrs['href']
            for child in node.children:
                r = find(child)
                if r:
                    return r
        elif hasattr(node, 'children'):
            for child in node.children:
                r = find(child)
                if r:
                    return r
        return None
    return find(doc)

###############################################################################
# Text extraction
###############################################################################

def get_text_nodes_all(elem):
    """Get all text nodes recursively (in order)"""
    result = []
    def traverse(node):
        if node.node_type == Node.TEXT_NODE:
            result.append(node.data)
        elif node.node_type == Node.ELEMENT_NODE:
            for child in node.children:
                traverse(child)
    for child in elem.children:
        traverse(child)
    return result

###############################################################################
# Main
###############################################################################

HELP_TEXT = """\
htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    htmlq [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]"""

def main():
    # Manual argument parsing to match clap's behavior
    args_in = sys.argv[1:]

    # Flags
    show_help = False
    show_version = False
    detect_base = False
    ignore_whitespace = False
    pretty = False
    text_mode = False

    # Options
    attribute = None
    base_url = None
    filename = None
    output_file = None
    remove_nodes_list = []

    # Positional (selectors)
    selectors = []

    i = 0
    end_of_options = False

    while i < len(args_in):
        arg = args_in[i]

        if end_of_options:
            selectors.append(arg)
            i += 1
            continue

        if arg == '--':
            end_of_options = True
            i += 1
            continue

        if arg in ('-h', '--help'):
            show_help = True
            i += 1
        elif arg in ('-V', '--version'):
            show_version = True
            i += 1
        elif arg in ('-B', '--detect-base'):
            detect_base = True
            i += 1
        elif arg in ('-w', '--ignore-whitespace'):
            ignore_whitespace = True
            i += 1
        elif arg in ('-p', '--pretty'):
            pretty = True
            i += 1
        elif arg in ('-t', '--text'):
            text_mode = True
            i += 1
        elif arg in ('-a', '--attribute'):
            i += 1
            if i < len(args_in):
                attribute = args_in[i]
                i += 1
        elif arg.startswith('--attribute='):
            attribute = arg[len('--attribute='):]
            i += 1
        elif arg in ('-b', '--base'):
            i += 1
            if i < len(args_in):
                base_url = args_in[i]
                i += 1
        elif arg.startswith('--base='):
            base_url = arg[len('--base='):]
            i += 1
        elif arg in ('-f', '--filename'):
            i += 1
            if i < len(args_in):
                filename = args_in[i]
                i += 1
        elif arg.startswith('--filename='):
            filename = arg[len('--filename='):]
            i += 1
        elif arg in ('-o', '--output'):
            i += 1
            if i < len(args_in):
                output_file = args_in[i]
                i += 1
        elif arg.startswith('--output='):
            output_file = arg[len('--output='):]
            i += 1
        elif arg in ('-r', '--remove-nodes'):
            i += 1
            if i < len(args_in):
                remove_nodes_list.append(args_in[i])
                i += 1
        elif arg.startswith('--remove-nodes='):
            remove_nodes_list.append(arg[len('--remove-nodes='):])
            i += 1
        elif arg.startswith('-'):
            # Unknown flag - try to handle short flags
            if len(arg) >= 2 and arg[1] in 'BhVwpt':
                # Known short flags that don't take args
                for ch in arg[1:]:
                    if ch == 'B': detect_base = True
                    elif ch == 'h': show_help = True
                    elif ch == 'V': show_version = True
                    elif ch == 'w': ignore_whitespace = True
                    elif ch == 'p': pretty = True
                    elif ch == 't': text_mode = True
                i += 1
            else:
                # Unknown
                print(f"error: Found argument '{arg}' which wasn't expected", file=sys.stderr)
                sys.exit(1)
        else:
            selectors.append(arg)
            i += 1

    if show_help:
        print(HELP_TEXT)
        return 0

    if show_version:
        print("htmlq 0.4.0")
        return 0

    # Default selector
    if not selectors:
        selectors = ['html']

    # Read input
    try:
        if filename:
            with open(filename, 'r', encoding='utf-8', errors='replace') as f:
                html_input = f.read()
        else:
            html_input = sys.stdin.read()
    except Exception as e:
        print(f"Error reading input: {e}", file=sys.stderr)
        return 1

    # Parse HTML
    try:
        doc = parse_html(html_input)
    except Exception as e:
        print(f"Error parsing HTML: {e}", file=sys.stderr)
        return 1

    # Remove nodes
    for sel_str in remove_nodes_list:
        try:
            remove_matching_nodes(doc, sel_str)
        except Exception as e:
            print(f"Error in remove-nodes selector '{sel_str}': {e}", file=sys.stderr)

    # Determine base URL
    effective_base = None
    if detect_base:
        found = detect_base_url(doc)
        if found:
            effective_base = found
        elif base_url:
            effective_base = base_url
    elif base_url:
        effective_base = base_url

    # Open output
    try:
        if output_file:
            out = open(output_file, 'w', encoding='utf-8')
        else:
            out = sys.stdout
    except Exception as e:
        print(f"Error opening output: {e}", file=sys.stderr)
        return 1

    try:
        # Apply selectors
        # First selector: select from document
        current_nodes = do_select(selectors[0], doc)

        # Chain remaining selectors
        for sel_str in selectors[1:]:
            current_nodes = do_select_within(sel_str, current_nodes)

        # Output results
        for node in current_nodes:
            if text_mode:
                texts = get_text_nodes_all(node)
                if ignore_whitespace:
                    # Output each non-whitespace text node on its own line
                    for text in texts:
                        if text.strip():  # not all whitespace
                            out.write(text)
                            out.write('\n')
                    out.write('\n')  # trailing newline per element
                else:
                    # Output all text concatenated + newline
                    out.write(''.join(texts))
                    out.write('\n')
            elif attribute is not None:
                val = node.get_attribute(attribute)
                if val is not None:
                    if effective_base:
                        val = resolve_url(effective_base, val)
                    out.write(val)
                    out.write('\n')
            else:
                if pretty:
                    html_str = serialize_element_pretty(node)
                    out.write(html_str)
                else:
                    html_str = serialize_element_normal(node)
                    out.write(html_str)
                    out.write('\n')
    finally:
        if output_file and out != sys.stdout:
            out.close()

    return 0

if __name__ == '__main__':
    sys.exit(main())
