def main():
    # Manual argument parsing to match clap's behavior
    args_in = sys.argv[1:]

    # Flags
    show_help = False
    show_version = False
    detect_base = False
    ignore_whitespace = False
    pretty = False
    text_mode = False

    # Options
    attribute = None
    base_url = None
    filename = None
    output_file = None
    remove_nodes_list = []

    # Positional (selectors)
    selectors = []

    i = 0
    end_of_options = False

    while i < len(args_in):
        arg = args_in[i]

        if end_of_options:
            selectors.append(arg)
            i += 1
            continue

        if arg == '--':
            end_of_options = True
            i += 1
            continue

        if arg in ('-h', '--help'):
            show_help = True
            i += 1
        elif arg in ('-V', '--version'):
            show_version = True
            i += 1
        elif arg in ('-B', '--detect-base'):
            detect_base = True
            i += 1
        elif arg in ('-w', '--ignore-whitespace'):
            ignore_whitespace = True
            i += 1
        elif arg in ('-p', '--pretty'):
            pretty = True
            i += 1
        elif arg in ('-t', '--text'):
            text_mode = True
            i += 1
        elif arg in ('-a', '--attribute'):
            i += 1
            if i < len(args_in):
                attribute = args_in[i]
                i += 1
        elif arg.startswith('--attribute='):
            attribute = arg[len('--attribute='):]
            i += 1
        elif arg in ('-b', '--base'):
            i += 1
            if i < len(args_in):
                base_url = args_in[i]
                i += 1
        elif arg.startswith('--base='):
            base_url = arg[len('--base='):]
            i += 1
        elif arg in ('-f', '--filename'):
            i += 1
            if i < len(args_in):
                filename = args_in[i]
                i += 1
        elif arg.startswith('--filename='):
            filename = arg[len('--filename='):]
            i += 1
        elif arg in ('-o', '--output'):
            i += 1
            if i < len(args_in):
                output_file = args_in[i]
                i += 1
        elif arg.startswith('--output='):
            output_file = arg[len('--output='):]
            i += 1
        elif arg in ('-r', '--remove-nodes'):
            i += 1
            if i < len(args_in):
                remove_nodes_list.append(args_in[i])
                i += 1
        elif arg.startswith('--remove-nodes='):
            remove_nodes_list.append(arg[len('--remove-nodes='):])
            i += 1
